import{_ as a,o as i,c as t,ae as l}from"./chunks/framework.RRduUuAx.js";const h=JSON.parse('{"title":"Runtime Performance Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"sessions/20260226-helios-market-research/12_RUNTIME_PERF_ARCHITECTURE.md","filePath":"sessions/20260226-helios-market-research/12_RUNTIME_PERF_ARCHITECTURE.md"}'),r={name:"sessions/20260226-helios-market-research/12_RUNTIME_PERF_ARCHITECTURE.md"};function n(o,e,s,c,d,p){return i(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="runtime-performance-architecture" tabindex="-1">Runtime Performance Architecture <a class="header-anchor" href="#runtime-performance-architecture" aria-label="Permalink to &quot;Runtime Performance Architecture&quot;">​</a></h1><p>Date: 2026-02-26</p><h2 id="objective" tabindex="-1">Objective <a class="header-anchor" href="#objective" aria-label="Permalink to &quot;Objective&quot;">​</a></h2><p>Define a low-overhead runtime architecture for Helios as an editor-disabled IDE shell where primary interactions are:</p><ul><li>agent chat UI (control plane)</li><li>direct PTY terminal UI (data plane)</li></ul><h2 id="performance-slos" tabindex="-1">Performance SLOs <a class="header-anchor" href="#performance-slos" aria-label="Permalink to &quot;Performance SLOs&quot;">​</a></h2><ul><li>Input-to-echo latency (p50): &lt;30 ms</li><li>Input-to-render latency (p50): &lt;60 ms</li><li>Renderer frame stability: 60 FPS target on active pane, graceful degradation under bursts</li><li>Concurrent terminals: 25 active sessions with no sustained UI lockup</li><li>Memory (steady-state): &lt;500 MB for reference workload profile</li></ul><h2 id="architecture-principles" tabindex="-1">Architecture Principles <a class="header-anchor" href="#architecture-principles" aria-label="Permalink to &quot;Architecture Principles&quot;">​</a></h2><ol><li>Split control plane and terminal data plane.</li><li>Keep PTY byte path off the main UI thread.</li><li>Use bounded buffers and explicit backpressure.</li><li>Render only what is visible and relevant.</li><li>Treat policy/audit as asynchronous side effects, not hot-path blockers.</li></ol><h2 id="process-and-thread-model" tabindex="-1">Process and Thread Model <a class="header-anchor" href="#process-and-thread-model" aria-label="Permalink to &quot;Process and Thread Model&quot;">​</a></h2><ul><li><p>Desktop host process (<code>ElectroBun</code>):</p><ul><li>window lifecycle</li><li>settings and feature flags</li><li>command palette and global UX state</li></ul></li><li><p>Runtime daemon process:</p><ul><li>local bus server (<code>helios.localbus.v1</code>)</li><li>lane/session orchestrator (<code>par</code>, <code>zellij</code>, <code>zmx</code>)</li><li>protocol adapters (<code>ACP</code>, <code>MCP</code>, <code>A2A</code>)</li></ul></li><li><p>Terminal renderer worker(s):</p><ul><li>active renderer backend (<code>ghostty</code> or <code>rio</code>)</li><li>PTY stream decoding and paint scheduling</li></ul></li><li><p>Optional share workers:</p><ul><li><code>upterm</code>, <code>tmate</code> lifecycle</li></ul></li></ul><h2 id="data-path-diagram" tabindex="-1">Data Path Diagram <a class="header-anchor" href="#data-path-diagram" aria-label="Permalink to &quot;Data Path Diagram&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User keystroke</span></span>\n<span class="line"><span>  -&gt; UI input handler</span></span>\n<span class="line"><span>  -&gt; terminal input queue (bounded)</span></span>\n<span class="line"><span>  -&gt; PTY write</span></span>\n<span class="line"><span>  -&gt; PTY output bytes</span></span>\n<span class="line"><span>  -&gt; renderer worker decode</span></span>\n<span class="line"><span>  -&gt; paint queue (frame-coalesced)</span></span>\n<span class="line"><span>  -&gt; GPU draw</span></span>\n<span class="line"><span>  -&gt; screen</span></span></code></pre></div><p>Hot-path rule:</p><ul><li>No policy, MCP, A2A, or audit work in this path.</li></ul><h2 id="control-path-diagram" tabindex="-1">Control Path Diagram <a class="header-anchor" href="#control-path-diagram" aria-label="Permalink to &quot;Control Path Diagram&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User action (run task / approve / share / switch renderer)</span></span>\n<span class="line"><span>  -&gt; local bus command</span></span>\n<span class="line"><span>  -&gt; runtime service handler</span></span>\n<span class="line"><span>  -&gt; adapter invocation (par/zellij/zmx/upterm/tmate/ACP/MCP/A2A)</span></span>\n<span class="line"><span>  -&gt; local bus events</span></span>\n<span class="line"><span>  -&gt; AG-UI mapping</span></span>\n<span class="line"><span>  -&gt; UI panels (timeline, approvals, status)</span></span></code></pre></div><p>Control-path rule:</p><ul><li>High-value events are structured and correlated, but do not block PTY rendering.</li></ul><h2 id="per-stage-latency-budget" tabindex="-1">Per-Stage Latency Budget <a class="header-anchor" href="#per-stage-latency-budget" aria-label="Permalink to &quot;Per-Stage Latency Budget&quot;">​</a></h2><h3 id="terminal-input-to-frame" tabindex="-1">Terminal input to frame <a class="header-anchor" href="#terminal-input-to-frame" aria-label="Permalink to &quot;Terminal input to frame&quot;">​</a></h3><ul><li>UI input capture: 1-3 ms</li><li>Input queue + PTY write: 1-5 ms</li><li>PTY processing and decode: 3-12 ms</li><li>Paint scheduling and composition: 4-20 ms</li><li>Total target: 10-40 ms typical, &lt;=60 ms p50 envelope</li></ul><h3 id="command-operations-non-hot-path" tabindex="-1">Command operations (non-hot-path) <a class="header-anchor" href="#command-operations-non-hot-path" aria-label="Permalink to &quot;Command operations (non-hot-path)&quot;">​</a></h3><ul><li>Local bus dispatch: &lt;=5 ms</li><li>Policy check: &lt;=10 ms</li><li>Adapter invocation overhead (excluding external tool runtime): &lt;=15 ms</li><li>UI state propagation: &lt;=20 ms</li></ul><h2 id="frame-pipeline-rules" tabindex="-1">Frame Pipeline Rules <a class="header-anchor" href="#frame-pipeline-rules" aria-label="Permalink to &quot;Frame Pipeline Rules&quot;">​</a></h2><ol><li>Frame-coalesce terminal updates to avoid repaint storms.</li><li>Drop intermediate paint events during extreme bursts; keep latest state.</li><li>Use dirty-region rendering where backend supports it.</li><li>Inactive panes/tabs are not continuously repainted.</li></ol><h2 id="buffering-and-backpressure" tabindex="-1">Buffering and Backpressure <a class="header-anchor" href="#buffering-and-backpressure" aria-label="Permalink to &quot;Buffering and Backpressure&quot;">​</a></h2><ul><li>Per-terminal output ring buffer with hard cap.</li><li>Shared global high-watermark to prevent memory runaway.</li><li>Backpressure stages: <ol><li>compress paint events</li><li>truncate non-visible historical output</li><li>surface &quot;render throttled&quot; indicator</li></ol></li></ul><p>Do not:</p><ul><li>block PTY process for UI pressure unless system safety threshold exceeded.</li></ul><h2 id="renderer-switching-architecture-ghostty-rio" tabindex="-1">Renderer Switching Architecture (<code>ghostty</code> / <code>rio</code>) <a class="header-anchor" href="#renderer-switching-architecture-ghostty-rio" aria-label="Permalink to &quot;Renderer Switching Architecture (`ghostty` / `rio`)&quot;">​</a></h2><h3 id="switch-states" tabindex="-1">Switch states <a class="header-anchor" href="#switch-states" aria-label="Permalink to &quot;Switch states&quot;">​</a></h3><ul><li><code>idle</code></li><li><code>switching</code></li><li><code>rollback</code></li><li><code>failed</code></li></ul><h3 id="sequence" tabindex="-1">Sequence <a class="header-anchor" href="#sequence" aria-label="Permalink to &quot;Sequence&quot;">​</a></h3><ol><li>Freeze paint ingestion briefly.</li><li>Snapshot visible terminal state metadata.</li><li>Initialize target renderer.</li><li>Rebind PTY streams and replay visible buffer.</li><li>Resume paint pipeline.</li></ol><p>Fallback:</p><ul><li>if any step fails, rollback to previous renderer.</li><li>if hot swap unsupported, perform fast restart with <code>zmx</code> + <code>zellij</code> restore.</li></ul><h2 id="lane-and-session-performance-par-zellij-zmx" tabindex="-1">Lane and Session Performance (<code>par</code> + <code>zellij</code> + <code>zmx</code>) <a class="header-anchor" href="#lane-and-session-performance-par-zellij-zmx" aria-label="Permalink to &quot;Lane and Session Performance (`par` + `zellij` + `zmx`)&quot;">​</a></h2><ul><li>Lane creation should avoid redundant clone work where possible.</li><li>Lane attach should be O(1) by session key lookup.</li><li><code>zmx</code> checkpoint frequency should be adaptive: <ul><li>high activity: less frequent checkpoints</li><li>idle/transition points: immediate checkpoint</li></ul></li></ul><h2 id="collaboration-overhead-upterm-tmate" tabindex="-1">Collaboration Overhead (<code>upterm</code> / <code>tmate</code>) <a class="header-anchor" href="#collaboration-overhead-upterm-tmate" aria-label="Permalink to &quot;Collaboration Overhead (`upterm` / `tmate`)&quot;">​</a></h2><ul><li>Share-session workers start on-demand only.</li><li>No background share daemon per terminal by default.</li><li>Enforce TTL and auto-stop to limit resource and security footprint.</li></ul><h2 id="memory-budget-allocation-reference" tabindex="-1">Memory Budget Allocation (Reference) <a class="header-anchor" href="#memory-budget-allocation-reference" aria-label="Permalink to &quot;Memory Budget Allocation (Reference)&quot;">​</a></h2><ul><li>Desktop host + UI state: 80-140 MB</li><li>Runtime daemon + orchestration: 70-120 MB</li><li>Renderer workers and buffers: 120-180 MB</li><li>25 terminal PTY/session overhead: 80-140 MB</li><li>Collaboration/process overhead: 20-40 MB</li></ul><p>Target total range: 370-620 MB</p><p>Note:</p><ul><li>To stay under 500 MB, aggressive buffer bounds and inactive-lane hibernation are required.</li></ul><h2 id="instrumentation-requirements" tabindex="-1">Instrumentation Requirements <a class="header-anchor" href="#instrumentation-requirements" aria-label="Permalink to &quot;Instrumentation Requirements&quot;">​</a></h2><p>Record at minimum:</p><ul><li>input_to_echo_ms</li><li>input_to_render_ms</li><li>frame_time_ms_p50/p95</li><li>renderer_queue_depth</li><li>terminal_output_backlog_bytes</li><li>lane_create_time_ms</li><li>session_restore_time_ms</li><li>memory_rss_mb</li></ul><h2 id="fault-and-recovery-strategy" tabindex="-1">Fault and Recovery Strategy <a class="header-anchor" href="#fault-and-recovery-strategy" aria-label="Permalink to &quot;Fault and Recovery Strategy&quot;">​</a></h2><ul><li>Renderer crash: restart renderer worker, rebind PTY streams, emit incident event.</li><li>Runtime daemon crash: restart daemon and restore lanes from <code>zmx</code> + <code>zellij</code> metadata.</li><li>Adapter failure (<code>par</code>/<code>upterm</code>/<code>tmate</code>): isolate to lane-level error, never crash global runtime.</li></ul><h2 id="implementation-guardrails" tabindex="-1">Implementation Guardrails <a class="header-anchor" href="#implementation-guardrails" aria-label="Permalink to &quot;Implementation Guardrails&quot;">​</a></h2><ol><li>No synchronous disk IO in PTY render loop.</li><li>No JSON serialization/deserialization of full terminal output frames in UI thread.</li><li>No unbounded arrays for event timelines or terminal history.</li><li>Policy, audit, and analytics must be async and cancellable.</li></ol><h2 id="verification-gates" tabindex="-1">Verification Gates <a class="header-anchor" href="#verification-gates" aria-label="Permalink to &quot;Verification Gates&quot;">​</a></h2><ul><li>Gate A: 8-terminal profile must sustain p50 input-to-render &lt;45 ms.</li><li>Gate B: 16-terminal profile must sustain p50 &lt;55 ms with no sustained frame collapse.</li><li>Gate C: 25-terminal profile must sustain p50 &lt;60 ms and memory &lt;=500 MB median over soak window.</li></ul>',55)])])}const m=a(r,[["render",n]]);export{h as __pageData,m as default};
